package com.foodflow.orders.repository;import com.foodflow.orders.entity.Order;import org.springframework.data.domain.Page;import org.springframework.data.domain.Pageable;import org.springframework.data.jpa.repository.JpaRepository;import java.util.*;public interface OrderRepository extends JpaRepository<Order,UUID>{Optional<Order> findByCustomerIdAndIdempotencyKey(UUID customerId,String key);Page<Order> findByCustomerId(UUID customerId,Pageable pageable);Page<Order> findByRestaurantId(UUID restaurantId,Pageable pageable);List<Order> findByStatus(String status);}
